const TOKEN_COOKIE_NAMES = ['accessToken', 'refreshToken', 'idToken'];

const requiredEnv = ['SCALEKIT_ENV_URL', 'SCALEKIT_CLIENT_ID', 'SCALEKIT_CLIENT_SECRET'];
