    return JSON.parse(decoded);
  } catch (error) {
    console.error('Failed to decode idToken payload:', error);
    return null;
  }
}

function getEmailFromClaims(claims) {
  return claims?.email || claims?.preferred_username || claims?.upn || claims?.sub || 'unknown user';
